using System.ComponentModel.DataAnnotations;using System.Security.Claims;using LocalPro.Web.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace LocalPro.Web.Pages.Professional;
public class DetailsModel(Marketplace m,LocalPro.Web.Data.AppDbContext db):PageModel{
 public Domain.Professional Pro{get;set;}=null!;[BindProperty]public DateTime LocalStart{get;set;}=DateTime.UtcNow.AddHours(27).Date.AddHours(10);[BindProperty,Required,StringLength(2000)]public string Description{get;set;}="";[BindProperty,Required,StringLength(300)]public string Address{get;set;}="";
 public async Task<IActionResult> OnPostSaveAsync(int id){if(User.Identity?.IsAuthenticated!=true)return Challenge();try{await m.Profile(id);var uid=User.FindFirstValue(ClaimTypes.NameIdentifier)!;if(!await Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.AnyAsync(db.Favorites,f=>f.UserId==uid&&f.ProfessionalId==id)){db.Favorites.Add(new(){UserId=uid,ProfessionalId=id});await db.SaveChangesAsync();}return RedirectToPage("/Favorites");}catch(RuleException){return NotFound();}}
 public async Task<IActionResult> OnPostReportAsync(int id,string reason,bool block){if(User.Identity?.IsAuthenticated!=true)return Challenge();var uid=User.FindFirstValue(ClaimTypes.NameIdentifier)!;try{var p=await m.Profile(id);if(string.IsNullOrWhiteSpace(reason)||reason.Length>2000){TempData["Error"]="Enter a report reason (up to 2000 characters).";return RedirectToPage(new{id});}db.Reports.Add(new(){UserId=uid,ProfessionalId=id,Reason=reason.Trim()});if(block&&p.UserId!=uid&&!await Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.AnyAsync(db.Blocks,b=>b.UserId==uid&&b.BlockedUserId==p.UserId))db.Blocks.Add(new(){UserId=uid,BlockedUserId=p.UserId});await db.SaveChangesAsync();TempData["Success"]="Report sent to the administrator.";return RedirectToPage(new{id});}catch(RuleException){return NotFound();}}
 public async Task<IActionResult> OnGetAsync(int id){try{Pro=await m.Profile(id);return Page();}catch(RuleException){return NotFound();}}
 public async Task<IActionResult> OnPostAsync(int id){if(User.Identity?.IsAuthenticated!=true)return Challenge();try{Pro=await m.Profile(id);if(!ModelState.IsValid)return Page();await m.Book(User.FindFirstValue(ClaimTypes.NameIdentifier)!,id,Marketplace.ToUtc(LocalStart),Description,Address);TempData["Success"]="Your appointment request was sent. The professional will confirm your time.";return RedirectToPage("/Appointments");}catch(RuleException ex){if(Pro==null)return NotFound();ModelState.AddModelError("",ex.Message);return Page();}}
}
